1 | /**
2 |  * Typed HTTP client for the Space Interpreter FastAPI backend.
3 |  * The browser communicates only with this backend — never with NASA or OpenRouter directly.
4 |  * No API keys are used here.
5 |  */
6 | 
7 | import type {
8 |   DailyNewsResponse,
9 |   StatusResponse,
10 |   SpaceStory,
11 |   StatusData,
12 |   ImageAnalysisResponse,
13 |   ImageAnalysisResult,
14 |   ImageAnalysisSuccess,
15 |   ChatMessage,
16 |   ChatAPIResponse,
17 |   ChatResponseData,
18 |   StoriesResponse,
19 |   StoriesData,
20 | } from './types';
21 | 
22 | // ---------------------------------------------------------------------------
23 | // Configuration
24 | // ---------------------------------------------------------------------------
25 | 
26 | function getApiBase(): string {
27 |   // NEXT_PUBLIC_API_URL is the only frontend env var — points to the FastAPI backend.
28 |   const base =
29 |     (typeof process !== 'undefined' &&
30 |       process.env.NEXT_PUBLIC_API_URL) ||
31 |     'http://localhost:8000';
32 |   return base.replace(/\/$/, '');
33 | }
34 | 
35 | // ---------------------------------------------------------------------------
36 | // Error type
37 | // ---------------------------------------------------------------------------
38 | 
39 | export class APIClientError extends Error {
40 |   constructor(
41 |     public readonly code: string,
42 |     message: string,
43 |   ) {
44 |     super(message);
45 |     this.name = 'APIClientError';
46 |   }
47 | }
48 | 
49 | // ---------------------------------------------------------------------------
50 | // Internal fetch helper
51 | // ---------------------------------------------------------------------------
52 | 
53 | async function apiFetch<T>(path: string): Promise<T> {
54 |   const url = `${getApiBase()}${path}`;
55 |   let res: Response;
56 | 
57 |   try {
58 |     res = await fetch(url, {
59 |       headers: { Accept: 'application/json' },
60 |       // Cache "no-store" so we always hit the backend — no stale Next.js cache
61 |       cache: 'no-store',
62 |     });
63 |   } catch {
64 |     throw new APIClientError(
65 |       'NETWORK_ERROR',
66 |       'تعذّر الاتصال بالخادم. تحقق من أن الخادم يعمل.',
67 |     );
68 |   }
69 | 
70 |   let json: unknown;
71 |   try {
72 |     json = await res.json();
73 |   } catch {
74 |     throw new APIClientError(
75 |       'PARSE_ERROR',
76 |       'تعذّر قراءة استجابة الخادم.',
77 |     );
78 |   }
79 | 
80 |   if (typeof json !== 'object' || json === null) {
81 |     throw new APIClientError('PARSE_ERROR', 'استجابة غير متوقعة من الخادم.');
82 |   }
83 | 
84 |   const body = json as { success?: boolean; error?: { code: string; message: string } };
85 | 
86 |   if (!res.ok || body.success === false) {
87 |     const code = body.error?.code ?? `HTTP_${res.status}`;
88 |     // Surface safe human-readable message — never expose backend internals
89 |     const message =
90 |       body.error?.message ?? 'حدث خطأ غير متوقع. يرجى المحاولة مجدداً.';
91 |     throw new APIClientError(code, message);
92 |   }
93 | 
94 |   return json as T;
95 | }
96 | 
97 | // ---------------------------------------------------------------------------
98 | // Public API functions
99 | // ---------------------------------------------------------------------------
100 | 
101 | /**
102 |  * Fetch today's NASA APOD Arabic space story.
103 |  * May take 5–30 seconds on first load (live NASA + AI generation).
104 |  */
105 | export async function fetchDailyNews(): Promise<SpaceStory> {
106 |   const res = await apiFetch<DailyNewsResponse>('/api/daily-news');
107 |   if (!res.success) {
108 |     throw new APIClientError(res.error.code, res.error.message);
109 |   }
110 |   return res.data;
111 | }
112 | 
113 | /**
114 |  * Fetch scheduler status and latest bulletin metadata.
115 |  * Fast — no external API calls on the backend side.
116 |  */
117 | export async function fetchStatus(): Promise<StatusData> {
118 |   const res = await apiFetch<StatusResponse>('/api/daily-news/status');
119 |   if (!res.success) {
120 |     throw new APIClientError(res.error.code, res.error.message);
121 |   }
122 |   return res.data;
123 | }
124 | 
125 | /**
126 |  * Upload an image and optional question to the backend vision analysis endpoint.
127 |  *
128 |  * Uses multipart/form-data — the backend handles all AI calls.
129 |  * No API key is used or accessible on the frontend.
130 |  *
131 |  * @param image   The image File object selected by the user.
132 |  * @param question  Optional Arabic question about the image.
133 |  */
134 | export async function analyzeImage(
135 |   image: File,
136 |   question?: string,
137 | ): Promise<ImageAnalysisResult> {
138 |   const url = `${getApiBase()}/api/analyze-image`;
139 | 
140 |   const formData = new FormData();
141 |   formData.append('image', image);
142 |   if (question && question.trim()) {
143 |     formData.append('question', question.trim());
144 |   }
145 | 
146 |   let res: Response;
147 |   try {
148 |     res = await fetch(url, {
149 |       method: 'POST',
150 |       body: formData,
151 |       // Do NOT set Content-Type header — browser sets it with boundary automatically
152 |       cache: 'no-store',
153 |     });
154 |   } catch {
155 |     throw new APIClientError(
156 |       'NETWORK_ERROR',
157 |       'تعذّر الاتصال بالخادم. تحقق من أن الخادم يعمل.',
158 |     );
159 |   }
160 | 
161 |   let json: unknown;
162 |   try {
163 |     json = await res.json();
164 |   } catch {
165 |     throw new APIClientError('PARSE_ERROR', 'تعذّر قراءة استجابة الخادم.');
166 |   }
167 | 
168 |   if (typeof json !== 'object' || json === null) {
169 |     throw new APIClientError('PARSE_ERROR', 'استجابة غير متوقعة من الخادم.');
170 |   }
171 | 
172 |   const body = json as ImageAnalysisResponse;
173 | 
174 |   if (!res.ok || body.success === false) {
175 |     const code = (body as { error?: { code: string; message: string } }).error?.code ?? `HTTP_${res.status}`;
176 |     const message =
177 |       (body as { error?: { code: string; message: string } }).error?.message ??
178 |       'حدث خطأ غير متوقع أثناء تحليل الصورة.';
179 |     throw new APIClientError(code, message);
180 |   }
181 | 
182 |   return (body as ImageAnalysisSuccess).data;
183 | }
184 | 
185 | /**
186 |  * Send a chat message and receive the AI's reply.
187 |  *
188 |  * @param messages  Full conversation history (role + content).
189 |  * @param imageContext  Optional ImageAnalysisResult to ground the chat.
190 |  */
191 | export async function sendChatMessage(
192 |   messages: ChatMessage[],
193 |   imageContext?: Record<string, unknown> | null,
194 | ): Promise<ChatResponseData> {
195 |   const url = `${getApiBase()}/api/chat`;
196 | 
197 |   let res: Response;
198 |   try {
199 |     res = await fetch(url, {
200 |       method: 'POST',
201 |       headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
202 |       body: JSON.stringify({
203 |         messages,
204 |         image_context: imageContext ?? null,
205 |       }),
206 |       cache: 'no-store',
207 |     });
208 |   } catch {
209 |     throw new APIClientError('NETWORK_ERROR', 'تعذّر الاتصال بالخادم. تحقق من أن الخادم يعمل.');
210 |   }
211 | 
212 |   let json: unknown;
213 |   try {
214 |     json = await res.json();
215 |   } catch {
216 |     throw new APIClientError('PARSE_ERROR', 'تعذّر قراءة استجابة الخادم.');
217 |   }
218 | 
219 |   if (typeof json !== 'object' || json === null) {
220 |     throw new APIClientError('PARSE_ERROR', 'استجابة غير متوقعة من الخادم.');
221 |   }
222 | 
223 |   const body = json as ChatAPIResponse;
224 |   if (!res.ok || body.success === false) {
225 |     const code = (body as { error?: { code: string; message: string } }).error?.code ?? `HTTP_${res.status}`;
226 |     const message =
227 |       (body as { error?: { code: string; message: string } }).error?.message ??
228 |       'حدث خطأ غير متوقع في المحادثة.';
229 |     throw new APIClientError(code, message);
230 |   }
231 | 
232 |   return (body as { success: true; data: ChatResponseData }).data;
233 | }
234 | 
235 | /**
236 |  * Fetch a list of APOD stories for browsing/archive.
237 |  *
238 |  * @param count     Number of days (1–10).
239 |  * @param endDate   End date YYYY-MM-DD. Defaults to today.
240 |  */
241 | export async function fetchStories(count = 5, endDate?: string): Promise<StoriesData> {
242 |   let path = `/api/stories?count=${count}`;
243 |   if (endDate) path += `&end_date=${endDate}`;
244 | 
245 |   const res = await apiFetch<StoriesResponse>(path);
246 |   if (!res.success) {
247 |     throw new APIClientError(res.error.code, res.error.message);
248 |   }
249 |   return res.data;
250 | }
