14 | export function useDailyNews(): UseDailyNewsResult {
15 |   const [story, setStory] = useState<SpaceStory | null>(null);
16 |   const [loading, setLoading] = useState<boolean>(true);
17 |   const [error, setError] = useState<string | null>(null);
18 |   const [fetchKey, setFetchKey] = useState<number>(0);
19 | 
20 |   const refetch = useCallback(() => {
21 |     setFetchKey((k) => k + 1);
22 |   }, []);
23 | 
24 |   useEffect(() => {
25 |     let cancelled = false;
26 | 
27 |     async function load() {
28 |       setLoading(true);
29 |       setError(null);
30 | 
31 |       try {
32 |         const data = await fetchDailyNews();
33 |         if (!cancelled) {
34 |           setStory(data);
35 |         }
36 |       } catch (err) {
37 |         if (!cancelled) {
38 |           if (err instanceof APIClientError) {
39 |             setError(err.message);
40 |           } else {
41 |             setError('حدث خطأ غير متوقع. يرجى المحاولة مجدداً.');
42 |           }
43 |         }
44 |       } finally {
45 |         if (!cancelled) {
46 |           setLoading(false);
47 |         }
48 |       }
49 |     }
50 | 
51 |     load();
52 | 
53 |     return () => {
54 |       cancelled = true;
55 |     };
56 |   }, [fetchKey]);
57 | 
