Contents of file frontend/hooks/useFavorites.ts:

1 | 'use client';
2 | 
3 | import { useState, useEffect, useCallback } from 'react';
4 | import type { StoryCard } from '@/lib/types';
5 | 
6 | const STORAGE_KEY = 'space_interpreter_favorites';
7 | 
8 | export interface UseFavoritesResult {
9 |   favorites: StoryCard[];
10 |   isFavorite: (id: string) => boolean;
11 |   toggleFavorite: (story: StoryCard) => void;
12 |   clearFavorites: () => void;
13 | }
14 | 
15 | function loadFromStorage(): StoryCard[] {
16 |   if (typeof window === 'undefined') return [];
17 |   try {
18 |     const raw = localStorage.getItem(STORAGE_KEY);
19 |     if (!raw) return [];
20 |     const parsed = JSON.parse(raw);
21 |     if (!Array.isArray(parsed)) return [];
22 |     return parsed as StoryCard[];
23 |   } catch {
24 |     return [];
25 |   }
26 | }
27 | 
28 | function saveToStorage(favorites: StoryCard[]): void {
29 |   if (typeof window === 'undefined') return;
30 |   try {
31 |     localStorage.setItem(STORAGE_KEY, JSON.stringify(favorites));
32 |   } catch {
33 |     // Storage quota exceeded or unavailable — fail silently
34 |   }
35 | }
36 | 
37 | export function useFavorites(): UseFavoritesResult {
38 |   const [favorites, setFavorites] = useState<StoryCard[]>([]);
39 | 
40 |   // Hydrate from localStorage after mount
41 |   useEffect(() => {
42 |     setFavorites(loadFromStorage());
43 |   }, []);
44 | 
45 |   const isFavorite = useCallback(
46 |     (id: string) => favorites.some((f) => f.id === id),
47 |     [favorites],
48 |   );
49 | 
50 |   const toggleFavorite = useCallback((story: StoryCard) => {
51 |     setFavorites((prev) => {
52 |       const exists = prev.some((f) => f.id === story.id);
53 |       const updated = exists
54 |         ? prev.filter((f) => f.id !== story.id)
55 |         : [story, ...prev];
56 |       saveToStorage(updated);
57 |       return updated;
58 |     });
59 |   }, []);
60 | 
61 |   const clearFavorites = useCallback(() => {
62 |     setFavorites([]);
63 |     saveToStorage([]);
64 |   }, []);
65 | 
66 |   return { favorites, isFavorite, toggleFavorite, clearFavorites };
67 | }
