+    };
+  });
+}
+
+// ── Modal ──────────────────────────────────────────────────────────────────
+function openModal(story) {
+  currentModalStory = story;
+  const overlay = document.getElementById('story-modal-overlay');
+
+  // Image or placeholder
+  const imgWrap = document.getElementById('modal-image-wrap');
+  if (story.image_url && story.media_type !== 'video') {
