+    imgWrap.style.backgroundPosition = 'center';
+    imgWrap.style.minHeight = '280px';
+    imgWrap.innerHTML = '';
+  } else if (story.media_type === 'video') {
+    imgWrap.style.background = 'rgba(0,240,255,.04)';
+    imgWrap.innerHTML = `<div style="display:grid;place-items:center;min-height:160px;padding:30px;text-align:center"><div style="font-size:40px;margin-bottom:10px">▶</div><p class="muted" style="font-size:13px">Video APOD</p></div>`;
+  } else {
+    imgWrap.style.background = 'linear-gradient(135deg,rgba(0,240,255,.06),rgba(123,0,255,.1))';
+    imgWrap.innerHTML = `<div style="display:grid;place-items:center;min-height:160px"><span style="font-size:40px;opacity:.3">✦</span></div>`;
+  }
+
+  document.getElementById('modal-tag').textContent = story.media_type === 'video' ? 'VIDEO / APOD' : 'APOD';
+  document.getElementById('modal-title').textContent = story.title;
+  document.getElementById('modal-date').textContent = story.date + ' · ' + (story.source || 'NASA APOD');
+  document.getElementById('modal-summary').textContent = story.summary || '';
+  document.getElementById('modal-copyright').textContent = story.copyright ? '© ' + story.copyright : '';
+
+  // NASA link
+  const nasaLink = document.getElementById('modal-nasa-link');
+  if (story.date) {
+    const d = story.date.replace(/-/g, '').slice(2);
+    nasaLink.href = `https://apod.nasa.gov/apod/ap${d}.html`;
+    nasaLink.style.display = '';
+  } else {
+    nasaLink.style.display = 'none';
+  }
+
+  // Fav button
+  const favBtn = document.getElementById('modal-fav-btn');
+  function updateFavBtn() {
+    const saved = isFav(story.id);
+    favBtn.textContent = saved ? '★ Saved' : '☆ Save to favorites';
+    favBtn.style.color = saved ? 'var(--gold)' : '';
+  }
+  updateFavBtn();
+  favBtn.onclick = () => { toggleStoreFav(story); updateFavBtn(); renderGrid(); };
+
+  overlay.style.display = '';
+  overlay.scrollTop = 0;
+}
+
+function closeModal() {
+  document.getElementById('story-modal-overlay').style.display = 'none';
+  currentModalStory = null;
+}
+
+document.getElementById('modal-close').onclick = closeModal;
+document.getElementById('story-modal-overlay').onclick = (e) => {
+  if (e.target === document.getElementById('story-modal-overlay')) closeModal();
+};
+document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });
+
+// ── Search & filter ────────────────────────────────────────────────────────
+document.getElementById('story-search').addEventListener('input', e => {
+  currentQuery = e.target.value;
+  renderGrid();
+});
+document.querySelectorAll('[data-filter]').forEach(btn => {
+  btn.onclick = () => {
+    document.querySelectorAll('.filter').forEach(b => b.classList.remove('active'));
+    btn.classList.add('active');
+    currentFilter = btn.dataset.filter;
+    renderGrid();
+  };
+});
+
+// ── Load more ─────────────────────────────────────────────────────────────
+document.getElementById('load-more').onclick = async () => {
+  const btn = document.getElementById('load-more');
+  btn.innerHTML = '<span class="loading"><i></i><i></i><i></i></span> Loading…';
+  btn.disabled = true;
+
+  const oldest = allStories[allStories.length - 1];
+  const endDate = oldest ? oldest.date : undefined;
+
+  // Calculate the day before the oldest so we don't refetch
+  let nextEnd;
+  if (endDate) {
+    const d = new Date(endDate);
+    d.setDate(d.getDate() - 1);
+    nextEnd = d.toISOString().slice(0, 10);
+  }
+
+  try {
+    const data = await AlTariqAPI.fetchStories(10, nextEnd);
+    const newStories = (data.stories || []).filter(s => !allStories.some(x => x.id === s.id));
+    allStories = [...allStories, ...newStories];
+    renderGrid();
+    btn.innerHTML = 'Load more archive signals';
+    btn.disabled = newStories.length === 0;
+    if (newStories.length === 0) btn.textContent = 'Archive synchronized';
+  } catch (err) {
+    btn.innerHTML = 'Retry load more';
+    btn.disabled = false;
+  }
+};
+
+// ── Initial load ──────────────────────────────────────────────────────────
+async function loadStories() {
+  try {
+    const data = await AlTariqAPI.fetchStories(10);
+    allStories = data.stories || [];
+    renderGrid();
+  } catch (err) {
+    document.getElementById('story-grid').innerHTML = `
+      <div class="card empty" style="grid-column:1/-1">
+        <h2 style="color:var(--danger)">Could not load stories</h2>
+        <p class="muted">${err.message || 'Backend may be offline.'}</p>
+        <button class="btn btn-ghost" onclick="loadStories()" style="margin-top:12px">Retry</button>
+      </div>`;
+  }
+}
+
+loadStories();
+</script>
+</body>
+</html>

