+          <div class="actions" style="margin-top:20px">
+            <button id="chat-with-context" class="btn btn-ghost" style="font-size:13px">
+              Continue in AI Chat with this image →
+            </button>
+          </div>
+        </div>
+      </div>
+    </section>
+
+  </main>
+</div>
+
+<script src="config.js"></script>
+<script src="api.js"></script>
+<script src="app.js"></script>
+<script>
+// ── Interpreter page ──────────────────────────────────────────────────────
+
+const input    = document.getElementById('image-file');
+const dropZone = document.getElementById('drop-zone');
+const preview  = document.getElementById('image-preview');
+const prevWrap = document.getElementById('image-preview-wrap');
+const empty    = document.getElementById('upload-empty');
+const analyze  = document.getElementById('analyze');
+const statusEl = document.getElementById('upload-status');
+
+let selectedFile = null;
+let lastResult   = null;
+
+// ── File validation ───────────────────────────────────────────────────────
+function validateFile(file) {
+  if (!file) return 'No file selected.';
+  if (!['image/jpeg','image/png','image/webp'].includes(file.type))
+    return 'Unsupported type. Use JPG, PNG, or WEBP.';
+  if (file.size > 5 * 1024 * 1024)
+    return 'File exceeds 5 MB limit.';
+  return null;
+}
+
+function showFile(file) {
+  const err = validateFile(file);
+  if (err) {
+    statusEl.className = 'status error';
+    statusEl.textContent = err;
+    return;
+  }
+  selectedFile = file;
+  const url = URL.createObjectURL(file);
+  preview.src = url;
+  document.getElementById('preview-filename').textContent = file.name;
+  prevWrap.classList.remove('hidden');
+  empty.classList.add('hidden');
+  analyze.disabled = false;
+  statusEl.className = 'status success';
+  statusEl.textContent = `${file.name} ready for interpretation.`;
+}
+
+// ── File input / drag-drop ────────────────────────────────────────────────
+input.onchange = () => showFile(input.files[0]);
+
+['dragenter','dragover'].forEach(ev => dropZone.addEventListener(ev, e => {
+  e.preventDefault(); dropZone.classList.add('dragging');
+}));
+['dragleave','drop'].forEach(ev => dropZone.addEventListener(ev, e => {
+  e.preventDefault(); dropZone.classList.remove('dragging');
+}));
+dropZone.addEventListener('drop', e => showFile(e.dataTransfer.files[0]));
+
+document.getElementById('remove-image').onclick = () => {
+  input.value = '';
+  selectedFile = null;
+  prevWrap.classList.add('hidden');
+  empty.classList.remove('hidden');
+  analyze.disabled = true;
+  statusEl.className = 'hidden';
+  // Reset result panel
+  resetResult();
+};
+
+// ── Result panel helpers ──────────────────────────────────────────────────
+function resetResult() {
+  document.getElementById('result-idle').style.display = '';
+  document.getElementById('result-loading').style.display = 'none';
+  document.getElementById('result-error').style.display = 'none';
+  document.getElementById('analysis-result').classList.add('hidden');
+  lastResult = null;
+}
+
+function showLoading() {
+  document.getElementById('result-idle').style.display = 'none';
+  document.getElementById('result-loading').style.display = '';
+  document.getElementById('result-error').style.display = 'none';
+  document.getElementById('analysis-result').classList.add('hidden');
+}
+
+function showError(msg) {
+  document.getElementById('result-idle').style.display = 'none';
+  document.getElementById('result-loading').style.display = 'none';
+  document.getElementById('result-error').style.display = '';
+  document.getElementById('result-error-msg').textContent = msg;
+  document.getElementById('analysis-result').classList.add('hidden');
+}
+
+function showResult(r) {
+  document.getElementById('result-idle').style.display = 'none';
+  document.getElementById('result-loading').style.display = 'none';
+  document.getElementById('result-error').style.display = 'none';
+
+  document.getElementById('result-title').textContent   = r.title || 'Analysis complete';
+  document.getElementById('result-summary').textContent = r.summary || '';
+  document.getElementById('result-science').textContent = r.scientific_explanation || '';
+
+  // Confidence badge
+  const badge = document.getElementById('result-confidence-badge');
+  const confMap = { high: 'HIGH CONFIDENCE', medium: 'MEDIUM CONFIDENCE', low: 'LOW CONFIDENCE' };
+  badge.textContent = confMap[r.confidence] || r.confidence || '';
+  badge.className = 'tag' + (r.confidence === 'high' ? ' green' : r.confidence === 'low' ? '' : '');
+
+  // Observations list
+  const obsList = document.getElementById('result-observations');
+  obsList.innerHTML = (r.observations || []).map(o => `<li style="margin-bottom:4px">${o}</li>`).join('');
+  document.getElementById('result-observations-block').style.display = r.observations?.length ? '' : 'none';
+
+  // Q&A
+  if (r.question_answer) {
+    document.getElementById('result-qa').textContent = r.question_answer;
+    document.getElementById('result-qa-block').style.display = '';
+  } else {
+    document.getElementById('result-qa-block').style.display = 'none';
+  }
+
+  // Narrative
+  if (r.story) {
+    document.getElementById('result-story').textContent = r.story;
+    document.getElementById('result-story-block').style.display = '';
+  } else {
+    document.getElementById('result-story-block').style.display = 'none';
+  }
+
+  // Non-space notice
+  document.getElementById('result-non-space-block').style.display = r.is_space_related === false ? '' : 'none';
+
+  document.getElementById('analysis-result').classList.remove('hidden');
+  document.getElementById('analysis-result').scrollIntoView({ behavior: 'smooth' });
+}
+
+// ── Analyze click ─────────────────────────────────────────────────────────
+analyze.onclick = async () => {
+  if (!selectedFile) return;
+  analyze.disabled = true;
+  analyze.innerHTML = '<span class="loading"><i></i><i></i><i></i></span> Interpreting…';
+  showLoading();
+
+  const question = document.getElementById('question-input').value.trim();
+
+  try {
+    const result = await AlTariqAPI.analyzeImage(selectedFile, question || undefined);
+    lastResult = result;
+    showResult(result);
+  } catch (err) {
+    showError(err.message || 'Analysis failed. Check that the backend is running.');
+  } finally {
+    analyze.disabled = false;
+    analyze.innerHTML = 'Analyze image';
+  }
+};
+
+// ── Chat with context ──────────────────────────────────────────────────────
+document.getElementById('chat-with-context').onclick = () => {
+  if (lastResult) {
+    // Store the result so chat.html can pick it up
+    sessionStorage.setItem('al-tariq-image-context', JSON.stringify(lastResult));
+  }
+  window.location.href = 'chat.html';
+};
+</script>
+</body>
+</html>

