+
+const form      = document.getElementById('chat-form');
+const inputEl   = document.getElementById('chat-input');
+const messages  = document.getElementById('messages');
+const sendBtn   = document.getElementById('send-btn');
+const errorBar  = document.getElementById('chat-error');
+const statusTag = document.getElementById('chat-status-tag');
+
+let conversationHistory = [];
+let imageContext = null;
+let sending = false;
+
+// ── Image context from interpreter page ──────────────────────────────────
+(function loadContext() {
+  const raw = sessionStorage.getItem('al-tariq-image-context');
+  if (!raw) return;
+  try {
+    const ctx = JSON.parse(raw);
+    imageContext = ctx;
+    document.getElementById('image-context-banner').style.display = '';
