+  });
+}
+rebindChips();
+
+// ── Message rendering ─────────────────────────────────────────────────────
+function appendMessage(role, content) {
+  const div = document.createElement('div');
+  div.className = 'message ' + (role === 'user' ? 'user' : 'ai');
+  const label = role === 'user' ? 'YOU' : 'AL-TARIQ AI';
+  div.innerHTML = `<small>${label} · ${new Date().toUTCString().slice(17,22)} UTC</small>${escapeHtml(content)}`;
