+      <a href="chat.html" class="active"><span>AI Space Chat</span></a>
+      <a href="stories.html"><span>Cosmos Stories</span></a>
+      <a href="favorites.html"><span>Favorites</span></a>
+    </nav>
+    <div class="side-footer">MISSION STATUS<br><b>MISSION AI ONLINE</b></div>
+  </aside>
+
+  <!-- ── Main ──────────────────────────────────────────────────────────── -->
+  <main class="main">
+    <div class="topbar">
+      <span class="crumb">AI CORE / CONVERSATION</span>
+      <span id="chat-status-tag" class="tag green">READY</span>
+    </div>
+
+    <section class="page-head">
+      <div>
+        <div class="eyebrow">ORBITAL KNOWLEDGE INTERFACE</div>
+        <h1>Ask the universe.</h1>
+        <p>A focused conversation space for black holes, stellar birth, pulsars, and everything between.</p>
+      </div>
+    </section>
+
+    <!-- Image context banner (shown when arriving from interpreter) -->
+    <div id="image-context-banner" style="display:none;margin-bottom:16px">
+      <div class="card" style="padding:14px 18px;display:flex;align-items:center;justify-content:space-between;gap:12px;background:rgba(0,240,255,.05);border-color:rgba(0,240,255,.2)">
+        <div>
+          <span class="eyebrow" style="display:block;margin-bottom:4px">IMAGE CONTEXT ACTIVE</span>
+          <span id="image-context-title" class="muted" style="font-size:13px"></span>
+        </div>
+        <button id="clear-context" class="btn" style="font-size:12px;padding:7px 12px">Clear context ✕</button>
+      </div>
+    </div>
+
+    <section class="card chat-shell">
+      <!-- Prompt chips -->
+      <div class="chips" id="chat-chips">
+        <button class="chip" data-prompt="What is a black hole?">What is a black hole?</button>
+        <button class="chip" data-prompt="How are stars born?">How are stars born?</button>
+        <button class="chip" data-prompt="Explain neutron star spin">Explain neutron star spin</button>
+        <button class="chip" data-prompt="What is a pulsar?">What is a pulsar?</button>
+      </div>
+
+      <!-- Messages area -->
+      <div id="messages" class="messages" aria-live="polite" aria-label="Chat messages">
+        <div class="message ai" id="welcome-msg">
+          <small>AL-TARIQ AI · READY</small>
+          Welcome to the interpreter. Ask me anything about the cosmos and I will translate the science into a clear signal.
+        </div>
+      </div>
+
+      <!-- Error bar -->
+      <div id="chat-error" style="display:none;padding:10px 14px;background:rgba(251,113,133,.08);border:1px solid rgba(251,113,133,.25);border-radius:10px;color:var(--danger);font-size:13px;margin-bottom:10px"></div>
+
+      <!-- Input form -->
+      <form id="chat-form" class="chat-form" autocomplete="off">
+        <input id="chat-input" type="text" placeholder="Ask about stars, black holes, pulsars…" maxlength="800" aria-label="Message">
+        <button class="btn btn-primary" type="submit" id="send-btn">Send</button>
+        <button class="btn" type="button" id="clear-chat-btn" title="Clear conversation">↺</button>
+      </form>
+      <div style="font-size:11px;color:var(--muted);margin-top:6px">Enter to send · max 800 characters per message</div>
+    </section>
+
