+<script src="api.js"></script>
+<script src="app.js"></script>
+<script>
+// ── Chat page ─────────────────────────────────────────────────────────────
+
+const form      = document.getElementById('chat-form');
+const inputEl   = document.getElementById('chat-input');
+const messages  = document.getElementById('messages');
+const sendBtn   = document.getElementById('send-btn');
+const errorBar  = document.getElementById('chat-error');
+const statusTag = document.getElementById('chat-status-tag');
+
+let conversationHistory = [];
+let imageContext = null;
+let sending = false;
+
+// ── Image context from interpreter page ──────────────────────────────────
+(function loadContext() {
+  const raw = sessionStorage.getItem('al-tariq-image-context');
+  if (!raw) return;
+  try {
+    const ctx = JSON.parse(raw);
+    imageContext = ctx;
+    document.getElementById('image-context-banner').style.display = '';
+    document.getElementById('image-context-title').textContent = ctx.title || 'Image context loaded';
+    // Replace generic chips with image-specific prompts
+    document.getElementById('chat-chips').innerHTML = `
+      <button class="chip" data-prompt="What is this object?">What is this object?</button>
+      <button class="chip" data-prompt="How was this formed?">How was this formed?</button>
+      <button class="chip" data-prompt="How far away is it?">How far away is it?</button>`;
+    rebindChips();
+  } catch {}
+})();
+
+document.getElementById('clear-context').onclick = () => {
+  sessionStorage.removeItem('al-tariq-image-context');
+  imageContext = null;
+  document.getElementById('image-context-banner').style.display = 'none';
+};
+
+// ── Prompt chips ──────────────────────────────────────────────────────────
+function rebindChips() {
+  document.querySelectorAll('[data-prompt]').forEach(b => {
+    b.onclick = () => { inputEl.value = b.dataset.prompt; inputEl.focus(); };
+  });
+}
+rebindChips();
+
+// ── Message rendering ─────────────────────────────────────────────────────
+function appendMessage(role, content) {
+  const div = document.createElement('div');
+  div.className = 'message ' + (role === 'user' ? 'user' : 'ai');
+  const label = role === 'user' ? 'YOU' : 'AL-TARIQ AI';
+  div.innerHTML = `<small>${label} · ${new Date().toUTCString().slice(17,22)} UTC</small>${escapeHtml(content)}`;
+  messages.appendChild(div);
+  messages.scrollTop = messages.scrollHeight;
+  return div;
+}
+
+function escapeHtml(str) {
+  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
+}
+
+function showTyping() {
+  const div = document.createElement('div');
+  div.className = 'message ai';
+  div.id = 'typing-indicator';
+  div.innerHTML = '<small>AL-TARIQ AI · PROCESSING</small><span class="loading"><i></i><i></i><i></i></span>';
+  messages.appendChild(div);
+  messages.scrollTop = messages.scrollHeight;
+}
+
+function removeTyping() {
+  const el = document.getElementById('typing-indicator');
+  if (el) el.remove();
+}
+
+// ── Send message ──────────────────────────────────────────────────────────
+form.onsubmit = async (e) => {
+  e.preventDefault();
+  const text = inputEl.value.trim();
+  if (!text || sending) return;
+  if (text.length > 800) {
+    errorBar.style.display = '';
+    errorBar.textContent = 'Message too long (max 800 characters).';
+    return;
+  }
+
+  errorBar.style.display = 'none';
+  sending = true;
+  sendBtn.disabled = true;
+  statusTag.textContent = 'PROCESSING';
+  statusTag.className = 'tag';
+
+  // Remove welcome message on first real send
+  const welcome = document.getElementById('welcome-msg');
+  if (welcome) welcome.remove();
+
+  conversationHistory.push({ role: 'user', content: text });
+  appendMessage('user', text);
+  inputEl.value = '';
+  showTyping();
+
+  try {
+    const data = await AlTariqAPI.sendChatMessage(conversationHistory, imageContext);
+    removeTyping();
+    const reply = data.reply || '';
+    conversationHistory.push({ role: 'assistant', content: reply });
+    appendMessage('assistant', reply);
+    statusTag.textContent = 'READY';
+    statusTag.className = 'tag green';
+  } catch (err) {
+    removeTyping();
+    errorBar.style.display = '';
+    errorBar.textContent = err.message || 'Could not reach the AI. Check the backend is running.';
+    // Roll back the failed user message from history so the state is consistent
+    conversationHistory.pop();
+    statusTag.textContent = 'ERROR';
+    statusTag.className = 'tag';
+    statusTag.style.color = 'var(--danger)';
+  } finally {
+    sending = false;
+    sendBtn.disabled = false;
+  }
+};
+
+// ── Clear conversation ────────────────────────────────────────────────────
+document.getElementById('clear-chat-btn').onclick = () => {
+  conversationHistory = [];
+  messages.innerHTML = `
+    <div class="message ai" id="welcome-msg">
+      <small>AL-TARIQ AI · READY</small>
+      Conversation cleared. What would you like to explore?
+    </div>`;
+  errorBar.style.display = 'none';
+  statusTag.textContent = 'READY';
+  statusTag.className = 'tag green';
+  statusTag.style.color = '';
+};
+</script>
+</body>
+</html>

