/* ── Starfield canvas (req 5) ─────────────────────────────────────────── */
#starfield-canvas{position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none}

/* ── Language toggle (req 4) — always isolated, top-right corner ──────── */
#lang-toggle{position:fixed;top:14px;right:18px;z-index:999;padding:6px 13px;border:1px solid rgba(0,240,255,.35);background:rgba(0,240,255,.07);color:var(--cyan);border-radius:8px;font-size:11px;font-weight:700;letter-spacing:.1em;cursor:pointer;backdrop-filter:blur(8px);transition:background .15s,border-color .15s;direction:ltr!important;font-family:"Space Mono",monospace}
#lang-toggle:hover{background:rgba(0,240,255,.18);border-color:var(--cyan)}
/* RTL override: mirror to left side so it doesn't overlap the date */
html[dir="rtl"] #lang-toggle{right:auto;left:18px;direction:ltr!important}

/* ── Comprehensive RTL overrides (req 3) ──────────────────────────────── */
html[dir="rtl"] body{text-align:right}
html[dir="rtl"] .app{direction:rtl}
html[dir="rtl"] .sidebar{border-right:0;border-left:1px solid var(--line)}
html[dir="rtl"] .main{padding-left:clamp(18px,4vw,60px);padding-right:clamp(18px,4vw,60px)}
html[dir="rtl"] .topbar,
html[dir="rtl"] .section-title,
html[dir="rtl"] .page-head,
html[dir="rtl"] .card-head,
html[dir="rtl"] .weather-row,
html[dir="rtl"] .hero-meta,
html[dir="rtl"] .actions,
html[dir="rtl"] .facts,
html[dir="rtl"] .story-card .story-copy,
html[dir="rtl"] .chat-form,
html[dir="rtl"] .result-grid,
html[dir="rtl"] .toolbar,
html[dir="rtl"] .filters,
html[dir="rtl"] .chips,
html[dir="rtl"] .tile-foot,
html[dir="rtl"] .page-head .actions{direction:rtl}
html[dir="rtl"] .nav a{direction:rtl;justify-content:flex-end}
html[dir="rtl"] .nav a .nav-dot{margin-right:0;margin-left:10px}
html[dir="rtl"] .brand{flex-direction:row-reverse}
html[dir="rtl"] .card{direction:rtl;text-align:right}
html[dir="rtl"] .message.user{justify-self:start}
html[dir="rtl"] .message.ai{justify-self:end}
html[dir="rtl"] .story-tile .tile-content{direction:rtl}
html[dir="rtl"] .hero{grid-template-columns:1fr 1.1fr}
html[dir="rtl"] .hero>div:first-child{order:2}
html[dir="rtl"] .hero-visual{order:1}
html[dir="rtl"] .grid-2,html[dir="rtl"] .grid-3{direction:rtl}
html[dir="rtl"] input,html[dir="rtl"] textarea{direction:rtl;text-align:right}
html[dir="rtl"] .chat-form input{direction:rtl}
html[dir="rtl"] .upload{direction:rtl}
html[dir="rtl"] .result-block{direction:rtl;text-align:right}
/* Keep tech labels / code always LTR */
html[dir="rtl"] .mono,
html[dir="rtl"] .eyebrow,
html[dir="rtl"] .tag,
html[dir="rtl"] #lang-toggle{direction:ltr!important;unicode-bidi:embed}
/* Topbar date must stay LTR */
html[dir="rtl"] .topbar .mono{direction:ltr!important}

