.hero-visual .jet{left:50%;top:50%;width:48%;height:36px;margin:-18px 0 0;transform-origin:0 50%;background:linear-gradient(90deg,rgba(255,255,255,.98) 0%,rgba(255,250,218,.92) 17%,rgba(255,224,139,.7) 56%,rgba(255,208,91,.08) 100%);clip-path:polygon(0 50%,100% 0,100% 100%);filter:blur(4px);animation:poleSweep var(--pulsar-speed,2.8s) ease-in-out infinite;opacity:calc(.68 + var(--beam-power, .84) * .32)}
