427 | /* ── Apply translation to a DOM element ────────────────────────────────────
428 |    Walks text nodes and translatable attributes.
429 |    ─────────────────────────────────────────────────────────────────────────── */
430 | function translateElement(el) {
431 |   if (!el || !(el instanceof Element)) return;
432 | 
433 |   // Translate text nodes (trim so "  Home  " still maps to "Home")
434 |   for (const node of el.childNodes) {
435 |     if (node.nodeType === Node.TEXT_NODE) {
436 |       const orig = node.textContent.trim();
437 |       if (orig && AR[orig]) {
438 |         node.textContent = node.textContent.replace(orig, t(orig));
439 |       }
440 |     }
441 |   }
442 | 
443 |   // Translate placeholder / aria-label attributes
444 |   if (el.placeholder && AR[el.placeholder]) el.placeholder = t(el.placeholder);
445 |   if (el.getAttribute && el.getAttribute('aria-label') && AR[el.getAttribute('aria-label')]) {
446 |     el.setAttribute('aria-label', t(el.getAttribute('aria-label')));
447 |   }
448 | 
449 |   // Recurse into children (but not script/style)
450 |   for (const child of el.children) {
451 |     if (!['SCRIPT', 'STYLE', 'CANVAS'].includes(child.tagName)) {
452 |       translateElement(child);
453 |     }
454 |   }
455 | }
