.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:34px}.crumb{color:var(--muted);font-size:12px;letter-spacing:.08em;text-transform:uppercase}.mobile-menu{display:none;background:transparent;border:1px solid var(--line);border-radius:10px;color:var(--ink);padding:8px}
h1,h2,h3,p{margin-top:0}.eyebrow{color:var(--cyan);font:11px/1.2 "Space Mono",monospace;letter-spacing:.15em;text-transform:uppercase}.display{font-size:clamp(42px,6vw,82px);line-height:.96;letter-spacing:-.055em;max-width:680px;margin:18px 0;background:linear-gradient(105deg,#fff 20%,#9beaff 54%,#9b7cff);-webkit-background-clip:text;background-clip:text;color:transparent}.subtitle{color:var(--muted);max-width:560px;font-size:16px}.muted{color:var(--muted)}.mono{font-family:"Space Mono",monospace;font-size:11px;letter-spacing:.06em}
.grid{display:grid;gap:18px}.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:24px;backdrop-filter:blur(16px);box-shadow:0 20px 70px rgba(0,0,0,.16);transition:border-color .25s,transform .25s}.card:hover{border-color:rgba(0,240,255,.28);transform:translateY(-2px)}.card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:18px}.card h2{font-size:18px;margin-bottom:5px}.card h3{font-size:15px;margin-bottom:5px}.section-title{display:flex;align-items:end;justify-content:space-between;margin:52px 0 18px}.section-title h2{font-size:25px;margin:0}.section-title p{color:var(--muted);margin:0;font-size:13px}
