.hero{min-height:480px;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:20px}.hero-visual{height:450px;position:relative;display:grid;place-items:center}.hero-visual:before{content:"";position:absolute;width:82%;height:82%;border-radius:50%;background:radial-gradient(circle,rgba(37,99,235,.21),transparent 61%);filter:blur(18px)}.orbit{position:absolute;width:78%;height:43%;border:1px solid rgba(0,240,255,.23);border-radius:50%;transform:rotate(-25deg);box-shadow:0 0 35px rgba(0,240,255,.08)}.orbit.two{width:62%;height:30%;transform:rotate(57deg);border-color:rgba(123,0,255,.24)}.pulsar{width:88px;height:88px;border-radius:50%;background:#fff;position:relative;z-index:2;box-shadow:0 0 8px 5px #bfdbfe,0 0 30px 18px #2563eb,0 0 90px 35px rgba(29,78,216,.8);animation:pulse 3.8s ease-in-out infinite}.jet{position:absolute;width:78%;height:22px;z-index:1;background:linear-gradient(90deg,transparent 1%,rgba(0,240,255,.02) 18%,rgba(0,240,255,.7) 49%,rgba(0,240,255,.05) 86%,transparent);clip-path:polygon(0 42%,100% 0,100% 100%,0 58%);filter:blur(5px);transform:rotate(-25deg);animation:precess 5s ease-in-out infinite}.jet.back{transform:rotate(155deg);animation-delay:-2.5s;opacity:.74}.visual-label{position:absolute;bottom:20px;right:9%;padding:8px 12px;border:1px solid rgba(0,240,255,.2);background:rgba(3,5,17,.6);border-radius:8px;color:var(--cyan);font:11px "Space Mono",monospace}
