.story-card{display:grid;grid-template-columns:1.02fr .98fr;overflow:hidden;padding:0}.story-card .story-copy{padding:28px}.story-image{min-height:280px;background:linear-gradient(135deg,rgba(0,240,255,.08),rgba(123,0,255,.16)),url("https://images-assets.nasa.gov/image/PIA12348/PIA12348~orig.jpg") center/cover}.icon-box{width:34px;height:34px;border:1px solid rgba(0,240,255,.25);color:var(--cyan);border-radius:10px;display:grid;place-items:center}.icon-box svg{width:17px}.story-copy p{color:var(--muted)}.facts{display:grid;gap:12px;margin-top:22px}.fact{display:flex;gap:11px;align-items:flex-start}.fact strong{display:block;font-size:13px}.fact span{color:var(--muted);font-size:12px}
.weather{background:linear-gradient(130deg,rgba(123,0,255,.14),rgba(15,23,42,.7));}.metric{font-size:34px;font-weight:700;letter-spacing:-.04em}.meter{height:7px;background:#1e293b;border-radius:99px;overflow:hidden;margin:16px 0 9px}.meter i{display:block;height:100%;width:64%;background:linear-gradient(90deg,var(--cyan),var(--purple));border-radius:inherit}.weather-list{display:grid;gap:13px}.weather-row{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:10px;color:var(--muted);font-size:12px}.weather-row b{color:var(--ink);font-weight:500}
.page-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:20px 0 30px}.page-head h1{font-size:clamp(32px,4vw,52px);letter-spacing:-.05em;margin:8px 0}.page-head p{color:var(--muted);max-width:560px}.upload{min-height:350px;border:1px dashed rgba(0,240,255,.38);border-radius:var(--radius);display:grid;place-items:center;text-align:center;background:radial-gradient(circle at center,rgba(0,240,255,.08),transparent 55%);padding:30px}.upload.dragging{background:rgba(0,240,255,.14);border-color:var(--cyan)}.upload-icon{width:56px;height:56px;margin:0 auto 15px;border-radius:16px;display:grid;place-items:center;color:var(--cyan);background:rgba(0,240,255,.1);box-shadow:0 0 30px rgba(0,240,255,.15)}.upload-icon svg{width:25px}.file-input{display:none}.constraints{display:flex;gap:8px;justify-content:center;flex-wrap:wrap;margin-top:16px}.preview{position:relative;min-height:350px;overflow:hidden;border-radius:var(--radius);background:#090e21}.preview img{width:100%;height:100%;min-height:350px;object-fit:cover}.preview .overlay{position:absolute;inset:0;background:linear-gradient(0deg,rgba(3,5,17,.8),transparent 60%);display:flex;align-items:end;padding:20px}.remove{position:absolute;top:14px;right:14px;background:rgba(3,5,17,.7);border:1px solid var(--line);color:#fff;border-radius:8px;padding:8px}.field{display:grid;gap:8px;margin-top:18px}.field label{font-size:12px;color:var(--muted)}.field input,.field textarea,.search{width:100%;background:rgba(3,5,17,.5);border:1px solid var(--line);color:var(--ink);border-radius:10px;padding:12px 13px}.field textarea{min-height:96px;resize:vertical}.result{margin-top:20px}.result h2{font-size:24px}.result-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.result-block{background:rgba(3,5,17,.35);border:1px solid var(--line);padding:16px;border-radius:12px}.result-block h3{color:var(--cyan);font-size:12px;text-transform:uppercase;letter-spacing:.1em}.result-block p{color:var(--muted);margin:0}
.chat-shell{min-height:600px;display:flex;flex-direction:column}.messages{flex:1;display:grid;align-content:start;gap:16px;max-height:520px;overflow:auto;padding:8px 0 22px}.message{max-width:76%;padding:14px 16px;border-radius:14px;border:1px solid var(--line)}.message.ai{background:rgba(0,240,255,.06);justify-self:start}.message.user{background:linear-gradient(130deg,rgba(123,0,255,.35),rgba(0,240,255,.12));justify-self:end}.message small{display:block;color:#64748b;font:10px "Space Mono",monospace;margin-bottom:5px}.chat-form{display:flex;gap:9px;border-top:1px solid var(--line);padding-top:18px}.chat-form input{flex:1}.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:20px}.chip{border:1px solid var(--line);background:transparent;color:var(--muted);border-radius:99px;padding:8px 12px;font-size:12px}.chip:hover{color:var(--cyan);border-color:var(--cyan)}
.toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-bottom:20px}.toolbar .search{flex:1;min-width:220px}.filters{display:flex;gap:7px;flex-wrap:wrap}.filter{border:1px solid var(--line);background:transparent;color:var(--muted);padding:9px 12px;border-radius:9px;font-size:12px}.filter.active,.filter:hover{border-color:var(--cyan);color:var(--cyan)}.story-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.story-tile{padding:0;overflow:hidden}.tile-image{height:170px;background:linear-gradient(135deg,rgba(0,240,255,.08),rgba(123,0,255,.18));background-position:center;background-size:cover}.tile-content{padding:17px}.tile-content h3{min-height:48px}.tile-content p{color:var(--muted);font-size:12px}.tile-foot{display:flex;align-items:center;justify-content:space-between;color:#64748b;font:10px "Space Mono",monospace}.favorite{border:0;background:transparent;color:#64748b;padding:4px}.favorite.saved{color:var(--gold);filter:drop-shadow(0 0 5px rgba(255,215,0,.7))}.empty{text-align:center;padding:80px 20px}.empty svg{color:var(--cyan);margin-bottom:15px}.empty h2{font-size:24px}
.status{padding:10px 12px;border-radius:9px;font-size:12px;margin-top:12px}.status.error{color:#fecdd3;background:rgba(251,113,133,.1);border:1px solid rgba(251,113,133,.25)}.status.success{color:#bbf7d0;background:rgba(100,245,178,.1);border:1px solid rgba(100,245,178,.25)}.hidden{display:none!important}.loading{display:inline-flex;gap:4px;align-items:center}.loading i{width:5px;height:5px;border-radius:50%;background:var(--cyan);animation:dot 1s infinite}.loading i:nth-child(2){animation-delay:.15s}.loading i:nth-child(3){animation-delay:.3s}
@keyframes pulse{0%,100%{transform:scale(.96);opacity:.9}50%{transform:scale(1.1);opacity:1}}@keyframes precess{0%,100%{transform:rotate(-29deg) translateY(6px);opacity:.7}50%{transform:rotate(-21deg) translateY(-6px);opacity:.95}}@keyframes blink{0%,100%{opacity:1}50%{opacity:.3}}@keyframes dot{0%,80%,100%{transform:scale(.6);opacity:.4}40%{transform:scale(1);opacity:1}}
@media(max-width:980px){.sidebar{width:82px;padding:22px 10px}.brand{justify-content:center;margin:0 0 32px}.brand>div:last-child,.nav-label,.nav a span,.side-footer{display:none}.nav a{justify-content:center}.main{padding-inline:24px}.hero{grid-template-columns:1fr}.hero-visual{height:320px;order:-1}.story-grid{grid-template-columns:repeat(2,1fr)}}
@media(max-width:640px){.app{display:block}.sidebar{position:fixed;inset:0 0 auto;height:auto;width:100%;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;border-right:0;border-bottom:1px solid var(--line)}.brand{margin:0}.brand>div:last-child{display:block}.nav{display:none;position:absolute;top:65px;left:12px;right:12px;padding:10px;background:rgba(3,5,17,.96);border:1px solid var(--line);border-radius:14px}.nav.open{display:grid}.nav a{justify-content:flex-start}.nav a span{display:inline}.mobile-menu{display:block}.main{padding:90px 15px 45px}.topbar{margin-bottom:24px}.display{font-size:48px}.grid-2,.grid-3,.story-card,.result-grid,.story-grid{grid-template-columns:1fr}.hero-visual{height:275px}.pulsar{width:64px;height:64px}.hero-meta{gap:14px}.story-image{min-height:210px}.page-head{display:block}.page-head .actions{margin-top:15px}.chat-form{align-items:stretch}.chat-form .btn{padding-inline:12px}.message{max-width:90%}}

/* Pulsar beams: anchored at the star and sweeping through a limited angle.
   The beams pivot back and forth; they never translate across the star. */
.hero-visual .jet{transform-origin:50% 50%;animation:poleSweep 2.8s ease-in-out infinite}
.hero-visual .jet.back{animation-name:poleSweepBack;animation-delay:-1.4s}
.hero-visual .orbit{display:none}
@keyframes poleSweep{0%,100%{transform:rotate(-64deg);opacity:.68}50%{transform:rotate(-43deg);opacity:1}}
@keyframes poleSweepBack{0%,100%{transform:rotate(116deg);opacity:.62}50%{transform:rotate(137deg);opacity:.94}}

/* Keep the generated page icons visible in the compact left rail. */
.nav a .nav-dot{display:inline-grid!important;width:18px;height:18px;flex:none;place-items:center;color:var(--cyan);font:16px/1 "Space Mono",monospace}
.nav a .nav-dot:before{content:"✦"}
.nav a:nth-child(1) .nav-dot:before{content:"◉"}
.nav a:nth-child(2) .nav-dot:before{content:"◌"}
.nav a:nth-child(3) .nav-dot:before{content:"▱"}
.nav a:nth-child(4) .nav-dot:before{content:"▤"}
.nav a:nth-child(5) .nav-dot:before{content:"♡"}
.nav a:nth-child(6) .nav-dot:before{content:"◇"}
.nav a:nth-child(7) .nav-dot:before{content:"⌁"}
.nav a:nth-child(8) .nav-dot:before{content:"◷"}
.nav a:nth-child(9) .nav-dot:before{content:"★"}
.nav a:nth-child(10) .nav-dot:before{content:"⚙"}
.nav a:nth-child(11) .nav-dot:before{content:"⌛"}
.nav a:nth-child(12) .nav-dot:before{content:"⌁"}
.language-toggle{border:1px solid rgba(0,240,255,.3);background:rgba(0,240,255,.06);color:var(--cyan);border-radius:8px;padding:7px 10px;font-size:11px;cursor:pointer}.language-toggle:hover{background:rgba(0,240,255,.14)}
.language-select{border:1px solid rgba(0,240,255,.3);background:#0b1530;color:var(--cyan);border-radius:8px;padding:7px 10px;font-size:11px;cursor:pointer}.language-select option{background:#0b1530;color:#fff}
html[dir="rtl"] body{text-align:right}html[dir="rtl"] .topbar,html[dir="rtl"] .section-title,html[dir="rtl"] .page-head,html[dir="rtl"] .card-head,html[dir="rtl"] .weather-row{direction:rtl}html[dir="rtl"] .hero-meta,html[dir="rtl"] .actions,html[dir="rtl"] .facts{direction:rtl}html[dir="rtl"] .story-card .story-copy{direction:rtl}html[dir="rtl"] .nav a{direction:rtl}html[dir="rtl"] .language-toggle{font-family:inherit}
