.language-select{position:fixed;top:18px;right:22px;z-index:30;box-shadow:0 8px 24px rgba(0,0,0,.28)}
html[dir="rtl"] .language-select{right:auto;left:22px}

/* Light neutral core and two clearly separated expanding polar cones. */
.hero-visual:before{background:radial-gradient(circle,rgba(255,235,180,.13),transparent 61%)}
.hero-visual .pulsar{background:radial-gradient(circle at 35% 30%,#fff 0 14%,#fff8dc 32%,#ffe9a8 58%,#f7c95c 78%,#8a5b16 100%);box-shadow:0 0 8px 4px rgba(255,255,235,.95),0 0 25px 11px rgba(255,221,137,.55),0 0 58px 22px rgba(255,195,72,.2)}
.hero-visual .jet{left:50%;top:50%;width:48%;height:36px;margin:-18px 0 0;transform-origin:0 50%;background:linear-gradient(90deg,rgba(255,255,255,.98) 0%,rgba(255,250,218,.92) 17%,rgba(255,224,139,.7) 56%,rgba(255,208,91,.08) 100%);clip-path:polygon(0 50%,100% 0,100% 100%);filter:blur(4px);animation:poleSweep var(--pulsar-speed,2.8s) ease-in-out infinite;opacity:calc(.68 + var(--beam-power, .84) * .32)}
.hero-visual .jet.back{animation-name:poleSweepBack;background:linear-gradient(90deg,rgba(255,255,255,.98) 0%,rgba(255,250,218,.88) 17%,rgba(255,224,139,.64) 56%,rgba(255,208,91,.06) 100%)}
.hero-visual .pulsar{animation:pulse 3.8s ease-in-out infinite!important;animation-play-state:running!important;will-change:transform,opacity}
.hero-visual .jet{animation-duration:var(--pulsar-speed,2.8s)!important;animation-iteration-count:infinite!important;animation-play-state:running!important;will-change:transform,opacity}
.hero-visual .pulsar{background:radial-gradient(circle at 35% 30%,#fff 0 14%,#f8fdff 32%,#9ee8ff 58%,#38aef5 78%,#164e9c 100%);box-shadow:0 0 8px 4px rgba(255,255,255,.98),0 0 25px 11px rgba(104,211,255,.62),0 0 58px 22px rgba(21,110,220,.28)}
.hero-visual .jet{background:linear-gradient(90deg,rgba(255,255,255,.99) 0%,rgba(225,248,255,.94) 17%,rgba(76,190,255,.76) 56%,rgba(22,105,220,.1) 100%)}
.hero-visual .jet.back{animation-name:poleSweepBack;animation-delay:0s;background:linear-gradient(90deg,rgba(255,255,255,.99) 0%,rgba(225,248,255,.94) 17%,rgba(76,190,255,.76) 56%,rgba(22,105,220,.1) 100%)}
@keyframes poleSweep{0%,100%{transform:rotate(-16deg)}50%{transform:rotate(16deg)}}
@keyframes poleSweepBack{0%,100%{transform:rotate(164deg)}50%{transform:rotate(196deg)}}
.favorite svg{width:17px!important;height:17px!important;display:block}

/* ── Starfield canvas (req 5) ─────────────────────────────────────────── */
#starfield-canvas{position:fixed;inset:0;width:100%;height:100%;z-index:-1;pointer-events:none}

/* ── Language toggle (req 4) — always isolated, top-right corner ──────── */
#lang-toggle{position:fixed;top:14px;right:18px;z-index:999;padding:6px 13px;border:1px solid rgba(0,240,255,.35);background:rgba(0,240,255,.07);color:var(--cyan);border-radius:8px;font-size:11px;font-weight:700;letter-spacing:.1em;cursor:pointer;backdrop-filter:blur(8px);transition:background .15s,border-color .15s;direction:ltr!important;font-family:"Space Mono",monospace}
#lang-toggle:hover{background:rgba(0,240,255,.18);border-color:var(--cyan)}
/* RTL override: mirror to left side so it doesn't overlap the date */
html[dir="rtl"] #lang-toggle{right:auto;left:18px;direction:ltr!important}

/* ── Comprehensive RTL overrides (req 3) ──────────────────────────────── */
