html[dir="rtl"] .page-head,
html[dir="rtl"] .card-head,
html[dir="rtl"] .weather-row,
html[dir="rtl"] .hero-meta,
html[dir="rtl"] .actions,
html[dir="rtl"] .facts,
html[dir="rtl"] .story-card .story-copy,
html[dir="rtl"] .chat-form,
html[dir="rtl"] .result-grid,
html[dir="rtl"] .toolbar,
html[dir="rtl"] .filters,
html[dir="rtl"] .chips,
html[dir="rtl"] .tile-foot,
html[dir="rtl"] .page-head .actions{direction:rtl}
