html[dir="rtl"] .chat-form input{direction:rtl}
html[dir="rtl"] .upload{direction:rtl}
html[dir="rtl"] .result-block{direction:rtl;text-align:right}
/* Keep tech labels / code always LTR */
html[dir="rtl"] .mono,
