19 |  * Throws an Error with a human-readable `.message` on any failure.
20 |  */
21 | async function _apiFetch(path, options = {}) {
22 |   const url = _base() + path;
23 |   let res;
24 |   try {
25 |     res = await fetch(url, { cache: 'no-store', ...options });
26 |   } catch {
27 |     throw new Error('Cannot reach the backend. Make sure the FastAPI server is running.');
