156 | <script>
157 | // ── Interpreter page ──────────────────────────────────────────────────────
158 | 
159 | const input    = document.getElementById('image-file');
160 | const dropZone = document.getElementById('drop-zone');
161 | const preview  = document.getElementById('image-preview');
162 | const prevWrap = document.getElementById('image-preview-wrap');
163 | const empty    = document.getElementById('upload-empty');
164 | const analyze  = document.getElementById('analyze');
165 | const statusEl = document.getElementById('upload-status');
166 | 
167 | let selectedFile = null;
168 | let lastResult   = null;
169 | 
170 | // ── File validation ───────────────────────────────────────────────────────
171 | function validateFile(file) {
172 |   if (!file) return 'No file selected.';
173 |   if (!['image/jpeg','image/png','image/webp'].includes(file.type))
174 |     return t('Unsupported type. Use JPG, PNG, or WEBP.');
175 |   if (file.size > 5 * 1024 * 1024)
176 |     return t('File exceeds 5 MB limit.');
177 |   return null;
178 | }
179 | 
180 | function showFile(file) {
181 |   const err = validateFile(file);
182 |   if (err) {
183 |     statusEl.className = 'status error';
184 |     statusEl.textContent = err;
185 |     return;
186 |   }
187 |   selectedFile = file;
188 |   const url = URL.createObjectURL(file);
189 |   preview.src = url;
190 |   document.getElementById('preview-filename').textContent = file.name;
191 |   prevWrap.classList.remove('hidden');
192 |   empty.classList.add('hidden');
193 |   analyze.disabled = false;
194 |   statusEl.className = 'status success';
195 |   statusEl.textContent = `${file.name} ${t('ready for interpretation.')}`;
196 | }
197 | 
198 | // ── File input / drag-drop ────────────────────────────────────────────────
199 | input.onchange = () => showFile(input.files[0]);
200 | 
201 | ['dragenter','dragover'].forEach(ev => dropZone.addEventListener(ev, e => {
202 |   e.preventDefault(); dropZone.classList.add('dragging');
203 | }));
204 | ['dragleave','drop'].forEach(ev => dropZone.addEventListener(ev, e => {
205 |   e.preventDefault(); dropZone.classList.remove('dragging');
206 | }));
207 | dropZone.addEventListener('drop', e => showFile(e.dataTransfer.files[0]));
208 | 
209 | document.getElementById('remove-image').onclick = () => {
210 |   input.value = '';
211 |   selectedFile = null;
212 |   prevWrap.classList.add('hidden');
213 |   empty.classList.remove('hidden');
214 |   analyze.disabled = true;
215 |   statusEl.className = 'hidden';
216 |   // Reset result panel
217 |   resetResult();
218 | };
219 | 
220 | // ── Result panel helpers ──────────────────────────────────────────────────
221 | function resetResult() {
222 |   document.getElementById('result-idle').style.display = '';
223 |   document.getElementById('result-loading').style.display = 'none';
224 |   document.getElementById('result-error').style.display = 'none';
225 |   document.getElementById('analysis-result').classList.add('hidden');
226 |   lastResult = null;
227 | }
228 | 
229 | function showLoading() {
230 |   document.getElementById('result-idle').style.display = 'none';
231 |   document.getElementById('result-loading').style.display = '';
232 |   document.getElementById('result-error').style.display = 'none';
233 |   document.getElementById('analysis-result').classList.add('hidden');
234 | }
235 | 
236 | function showError(msg) {
237 |   document.getElementById('result-idle').style.display = 'none';
238 |   document.getElementById('result-loading').style.display = 'none';
239 |   document.getElementById('result-error').style.display = '';
240 |   document.getElementById('result-error-msg').textContent = msg;
241 |   document.getElementById('analysis-result').classList.add('hidden');
242 | }
243 | 
244 | function showResult(r) {
245 |   document.getElementById('result-idle').style.display = 'none';
246 |   document.getElementById('result-loading').style.display = 'none';
247 |   document.getElementById('result-error').style.display = 'none';
248 | 
249 |   document.getElementById('result-title').textContent   = r.title || 'Analysis complete';
250 |   document.getElementById('result-summary').textContent = r.summary || '';
251 |   document.getElementById('result-science').textContent = r.scientific_explanation || '';
252 | 
253 |   // Confidence badge
254 |   const badge = document.getElementById('result-confidence-badge');
255 |   const confMap = { high: t('HIGH CONFIDENCE'), medium: t('MEDIUM CONFIDENCE'), low: t('LOW CONFIDENCE') };
256 |   badge.textContent = confMap[r.confidence] || r.confidence || '';
257 |   badge.className = 'tag' + (r.confidence === 'high' ? ' green' : r.confidence === 'low' ? '' : '');
258 | 
259 |   // Observations list
260 |   const obsList = document.getElementById('result-observations');
261 |   obsList.innerHTML = (r.observations || []).map(o => `<li style="margin-bottom:4px">${o}</li>`).join('');
262 |   document.getElementById('result-observations-block').style.display = r.observations?.length ? '' : 'none';
263 | 
264 |   // Q&A
265 |   if (r.question_answer) {
266 |     document.getElementById('result-qa').textContent = r.question_answer;
267 |     document.getElementById('result-qa-block').style.display = '';
268 |   } else {
269 |     document.getElementById('result-qa-block').style.display = 'none';
270 |   }
271 | 
272 |   // Narrative
273 |   if (r.story) {
274 |     document.getElementById('result-story').textContent = r.story;
275 |     document.getElementById('result-story-block').style.display = '';
276 |   } else {
277 |     document.getElementById('result-story-block').style.display = 'none';
278 |   }
279 | 
280 |   // Non-space notice
281 |   document.getElementById('result-non-space-block').style.display = r.is_space_related === false ? '' : 'none';
282 | 
283 |   document.getElementById('analysis-result').classList.remove('hidden');
284 |   document.getElementById('analysis-result').scrollIntoView({ behavior: 'smooth' });
285 | }
286 | 
287 | // ── Analyze click ─────────────────────────────────────────────────────────
288 | analyze.onclick = async () => {
289 |   if (!selectedFile) return;
290 |   analyze.disabled = true;
291 |   analyze.innerHTML = `<span class="loading"><i></i><i></i><i></i></span> ${t('Analysing…')}`;
292 |   showLoading();
293 | 
294 |   const question = document.getElementById('question-input').value.trim();
295 | 
296 |   try {
297 |     const result = await AlTariqAPI.analyzeImage(selectedFile, question || undefined);
298 |     lastResult = result;
299 |     showResult(result);
300 |   } catch (err) {
301 |     showError(err.message || t('Analysis failed. Check that the backend is running.'));
302 |   } finally {
303 |     analyze.disabled = false;
304 |     analyze.innerHTML = t('Analyze image');
305 |   }
306 | };
307 | 
308 | // ── Chat with context ──────────────────────────────────────────────────────
309 | document.getElementById('chat-with-context').onclick = () => {
310 |   if (lastResult) {
311 |     // Store the result so chat.html can pick it up
312 |     sessionStorage.setItem('al-tariq-image-context', JSON.stringify(lastResult));
313 |   }
314 |   window.location.href = 'chat.html';
315 | };
316 | </script>
317 | </body>
318 | </html>
