2 |  * Al-Tariq — centralized API client for the Space Interpreter FastAPI backend.
3 |  *
4 |  * All backend communication goes through this module.
5 |  * No NASA or OpenRouter keys are used here — everything stays server-side.
6 |  *
7 |  * Backend base URL comes from config.js (window.AL_TARIQ_API_URL).
8 |  * Default: http://localhost:8000
9 |  */
10 | 
11 | /* ─── helpers ─────────────────────────────────────────────────────────────── */
12 | 
13 | function _base() {
14 |   return (window.AL_TARIQ_API_URL || 'http://localhost:8000').replace(/\/$/, '');
15 | }
16 | 
17 | /**
18 |  * Generic fetch wrapper that normalises the backend {success, data} envelope.
19 |  * Throws an Error with a human-readable `.message` on any failure.
20 |  */
21 | async function _apiFetch(path, options = {}) {
22 |   const url = _base() + path;
23 |   let res;
24 |   try {
25 |     res = await fetch(url, { cache: 'no-store', ...options });
26 |   } catch {
27 |     throw new Error('Cannot reach the backend. Make sure the FastAPI server is running.');
28 |   }
29 | 
30 |   let json;
31 |   try {
32 |     json = await res.json();
33 |   } catch {
34 |     throw new Error('Unexpected response from server (not JSON).');
35 |   }
36 | 
37 |   if (!res.ok || json.success === false) {
38 |     const msg = json?.error?.message || `HTTP ${res.status}`;
39 |     throw new Error(msg);
40 |   }
41 | 
42 |   return json.data;
43 | }
44 | 
45 | /* ─── public API ──────────────────────────────────────────────────────────── */
46 | 
