48 |  * GET /api/daily-news
49 |  * Returns the AI-generated SpaceStory for today's NASA APOD.
50 |  * May take 5–30 seconds on first call.
51 |  * @returns {Promise<SpaceStory>}
52 |  */
53 | async function fetchDailyNews() {
54 |   return _apiFetch('/api/daily-news');
55 | }
56 | 
