58 |  * GET /api/daily-news/status
59 |  * Returns scheduler metadata and latest bulletin info. Fast — no external calls.
60 |  * @returns {Promise<StatusData>}
61 |  */
62 | async function fetchDailyNewsStatus() {
63 |   return _apiFetch('/api/daily-news/status');
64 | }
65 | 
