67 |  * GET /api/stories?count=N&end_date=YYYY-MM-DD
68 |  * Returns a list of NASA APOD entries. No AI call — pure data.
69 |  * @param {number} count   1–10
70 |  * @param {string} [endDate]  YYYY-MM-DD, defaults to today
71 |  * @returns {Promise<{stories: StoryCard[], count: number}>}
72 |  */
73 | async function fetchStories(count = 10, endDate) {
74 |   let path = `/api/stories?count=${count}`;
75 |   if (endDate) path += `&end_date=${encodeURIComponent(endDate)}`;
