80 |  * POST /api/analyze-image
81 |  * Sends a space image (multipart/form-data) to the vision AI.
82 |  * @param {File}   imageFile   JPEG/PNG/WEBP, max 5 MB
83 |  * @param {string} [question]  Optional question (max 400 chars)
84 |  * @returns {Promise<ImageAnalysisResult>}
85 |  */
86 | async function analyzeImage(imageFile, question) {
87 |   const formData = new FormData();
88 |   formData.append('image', imageFile);          // field name must be exactly "image"
89 |   if (question && question.trim()) {
90 |     formData.append('question', question.trim()); // field name must be exactly "question"
91 |   }
92 |   // Do NOT set Content-Type — the browser sets it with the correct boundary.
93 |   return _apiFetch('/api/analyze-image', { method: 'POST', body: formData });
94 | }
