97 |  * POST /api/chat
98 |  * Multi-turn space AI chat. Stateless — pass the full history each time.
99 |  * @param {Array<{role: string, content: string}>} messages  Full conversation history
100 |  * @param {object|null} [imageContext]  Optional ImageAnalysisResult from analyzeImage()
101 |  * @returns {Promise<{reply: string, role: string}>}
102 |  */
103 | async function sendChatMessage(messages, imageContext) {
104 |   // Sanitise image_context — only the five keys the backend forwards
105 |   let safeContext = null;
106 |   if (imageContext) {
107 |     safeContext = {};
108 |     for (const key of ['title', 'summary', 'observations', 'scientific_explanation', 'confidence']) {
109 |       if (imageContext[key] !== undefined) safeContext[key] = imageContext[key];
110 |     }
111 |   }
112 | 
113 |   return _apiFetch('/api/chat', {
114 |     method: 'POST',
115 |     headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
116 |     body: JSON.stringify({ messages, image_context: safeContext }),
117 |   });
118 | }
