125 | /**
126 |  * Upload an image and optional question to the backend vision analysis endpoint.
127 |  *
128 |  * Uses multipart/form-data — the backend handles all AI calls.
129 |  * No API key is used or accessible on the frontend.
130 |  *
131 |  * @param image   The image File object selected by the user.
132 |  * @param question  Optional Arabic question about the image.
133 |  */
134 | export async function analyzeImage(
135 |   image: File,
136 |   question?: string,
137 | ): Promise<ImageAnalysisResult> {
138 |   const url = `${getApiBase()}/api/analyze-image`;
